Item.method_code:
            Innovator inn = this.getInnovator();

            try
            {
                //保存時、対象マルQページと対象必要資料に値がある場合、必要資料は、マルQページに紐づいている必要資料かチェックする
                var thisId = this.getID();
                var h4_rel_mq = this.getProperty("h4_rel_mq","");
                var h4_rel_reqdoc = this.getProperty("h4_rel_reqdoc","");
                
                //対象マルQページと対象必要資料に値がある場合チャックを実行する
                if (!string.IsNullOrEmpty(h4_rel_mq) && !string.IsNullOrEmpty(h4_rel_reqdoc))
                {
                    List<string> relatedList = new List<string>();
                    
                    var relItemNames = "h4_MQPage ReqDoc";
                    var relationships = inn.newItem(relItemNames,"get");
                    relationships.setProperty("source_id",h4_rel_mq);
                    relationships.setAttribute("select", "related_id");
                    relationships = relationships.apply();
                    var count = relationships.getItemCount();
                    
                    for (var i = 0; i < count; i++)
                    {
                        var relationship = relationships.getItemByIndex(i);
                        var item_id =  relationship.getProperty("related_id");
                        if(!String.IsNullOrEmpty(item_id))
                        {
                            relatedList.Add(item_id);
                        }
                    }
                    
                    if (!relatedList.Contains(h4_rel_reqdoc))
                    {
                        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0601"));
                    }
                }

                return this;
            }
            catch (Exception e)
            {
                // Item err = inn.newError("Error02:" + e.Message);
                // err.setErrorDetail(e.StackTrace);
                // return err;
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
            }
        }

